using System.Text;using InventoryService.Data;using InventoryService.Services;using Microsoft.AspNetCore.Authentication.JwtBearer;using Microsoft.EntityFrameworkCore;using Microsoft.IdentityModel.Tokens;using Serilog;Log.Logger=new LoggerConfiguration().WriteTo.Console().WriteTo.File("logs/inventory-service-.log",rollingInterval:RollingInterval.Day).CreateLogger();var b=WebApplication.CreateBuilder(args);b.Host.UseSerilog();b.Services.AddControllers();b.Services.AddEndpointsApiExplorer();b.Services.AddSwaggerGen();b.Services.AddExceptionHandler<GlobalExceptionHandler>();b.Services.AddProblemDetails();b.Services.AddDbContext<InventoryDbContext>(o=>o.UseNpgsql(b.Configuration.GetConnectionString("InventoryDb")));var k=Encoding.UTF8.GetBytes(b.Configuration["Jwt:Key"]!);b.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new TokenValidationParameters{ValidateIssuer=false,ValidateAudience=false,ValidateLifetime=true,ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(k),RoleClaimType=System.Security.Claims.ClaimTypes.Role});b.Services.AddAuthorization();b.Services.AddScoped<IInventory,Inventory>();var a=b.Build();a.UseExceptionHandler();a.UseSwagger();a.UseSwaggerUI();a.UseAuthentication();a.UseAuthorization();a.MapControllers();a.Run();